// Left at its default of true, UIKit synthesises constraints from the view's frame
// and autoresizing mask, and they contradict yours:
//   "Unable to simultaneously satisfy constraints ... NSAutoresizingMaskLayoutConstraint"
// A view created in code starts at .zero, so everything lands in the top-left corner.

// Make it hard to forget
extension UIView {
  static func autoLayout() -> Self {
    let view = Self()
    view.translatesAutoresizingMaskIntoConstraints = false
    return view
  }
}
let title = UILabel.autoLayout()

// Do NOT turn it off on views you do not constrain yourself: a view controller's root
// view, a cell's contentView, or anything you position with frames.
// Interface Builder already sets it false, and UIStackView sets it on arranged subviews.

final class MessageCell: UITableViewCell {
  private let title = UILabel()
  private let body = UILabel()

  override init(style: UITableViewCell.CellStyle, reuseIdentifier: String?) {
    super.init(style: style, reuseIdentifier: reuseIdentifier)
    [title, body].forEach {
      $0.numberOfLines = 0                        // 0 = as many lines as the text needs
      $0.translatesAutoresizingMaskIntoConstraints = false
      contentView.addSubview($0)                  // constraints go on contentView, not the cell
    }

    let bottom = body.bottomAnchor.constraint(equalTo: contentView.bottomAnchor, constant: -12)
    bottom.priority = UILayoutPriority(999)       // yields while the cell is briefly unsized

    NSLayoutConstraint.activate([
      title.topAnchor.constraint(equalTo: contentView.topAnchor, constant: 12),
      title.leadingAnchor.constraint(equalTo: contentView.layoutMarginsGuide.leadingAnchor),
      title.trailingAnchor.constraint(equalTo: contentView.layoutMarginsGuide.trailingAnchor),
      body.topAnchor.constraint(equalTo: title.bottomAnchor, constant: 4),
      body.leadingAnchor.constraint(equalTo: title.leadingAnchor),
      body.trailingAnchor.constraint(equalTo: title.trailingAnchor),
      bottom,   // the chain reaches the bottom, so the height is solvable
    ])
  }
  required init?(coder: NSCoder) { fatalError("use init(style:reuseIdentifier:)") }
}

