private var heightConstraint: NSLayoutConstraint!   // keep the reference, change the constant

func setExpanded(_ expanded: Bool, animated: Bool) {
  heightConstraint.constant = expanded ? 240 : 88
  guard animated else { view.layoutIfNeeded(); return }
  UIView.animate(withDuration: 0.3) { self.view.layoutIfNeeded() }
}

// Structural change: hold both sets and swap them. Never build new ones per update —
// they accumulate invisibly until the layout is both slow and unsatisfiable.
private lazy var compact = [
  image.widthAnchor.constraint(equalToConstant: 44),
  label.leadingAnchor.constraint(equalTo: image.trailingAnchor, constant: 8),
]
private lazy var expanded = [
  image.widthAnchor.constraint(equalTo: card.widthAnchor),
  label.topAnchor.constraint(equalTo: image.bottomAnchor, constant: 8),
]

func applyLayout(isExpanded: Bool) {
  NSLayoutConstraint.deactivate(isExpanded ? compact : expanded)
  NSLayoutConstraint.activate(isExpanded ? expanded : compact)
}

// Priority: let one of two competing constraints win instead of breaking either
let preferredWidth = label.widthAnchor.constraint(equalToConstant: 320)
preferredWidth.priority = .defaultHigh   // 750, so it yields to a required trailing constraint
preferredWidth.isActive = true

// Changing a priority to or from .required on an installed constraint traps at runtime.

// Show and hide inside a stack view without touching constraints at all
detailsLabel.isHidden = !isExpanded

// Three different edges to pin to, with three different meanings
label.leadingAnchor.constraint(equalTo: view.leadingAnchor)                      // literal bounds
label.leadingAnchor.constraint(equalTo: view.layoutMarginsGuide.leadingAnchor)   // plus margins
label.leadingAnchor.constraint(equalTo: view.readableContentGuide.leadingAnchor) // readable width

// Margins are directional, so they mirror in right-to-left languages
view.directionalLayoutMargins = NSDirectionalEdgeInsets(top: 16, leading: 20,
                                                        bottom: 16, trailing: 20)
viewRespectsSystemMinimumLayoutMargins = false   // on a controller, to go below the system floor

// A stack view ignores its own margins until you ask it not to
stack.isLayoutMarginsRelativeArrangement = true
stack.directionalLayoutMargins = .init(top: 12, leading: 16, bottom: 12, trailing: 16)

// A layout guide replaces a transparent spacer view: nothing to draw, no touch target,
// no accessibility element, and no noise in the view debugger
let gutter = UILayoutGuide()
view.addLayoutGuide(gutter)
NSLayoutConstraint.activate([
  gutter.leadingAnchor.constraint(equalTo: left.trailingAnchor),
  gutter.trailingAnchor.constraint(equalTo: right.leadingAnchor),
  gutter.widthAnchor.constraint(greaterThanOrEqualToConstant: 8),
])

// Leading and trailing mirror automatically; left and right never do
NSLayoutConstraint.activate([
  icon.leadingAnchor.constraint(equalTo: view.layoutMarginsGuide.leadingAnchor),
  label.leadingAnchor.constraint(equalTo: icon.trailingAnchor, constant: 8),
  label.trailingAnchor.constraint(lessThanOrEqualTo: view.layoutMarginsGuide.trailingAnchor),
])

// Directional insets mirror; UIEdgeInsets does not
stack.directionalLayoutMargins = .init(top: 8, leading: 16, bottom: 8, trailing: 16)

// A directional glyph has to be told that it may flip
backButton.setImage(UIImage(named: "chevron")?.imageFlippedForRightToLeftLayoutDirection(),
                    for: .normal)
transportControls.semanticContentAttribute = .playback   // media controls must not mirror

// Dynamic Type: a text style plus the opt-in that keeps it updating
label.font = .preferredFont(forTextStyle: .body)
label.adjustsFontForContentSizeCategory = true
label.numberOfLines = 0

// Scale a custom font and a hard-coded spacing with the same metrics
let metrics = UIFontMetrics(forTextStyle: .body)
label.font = metrics.scaledFont(for: brandFont)
spacingConstraint.constant = metrics.scaledValue(for: 16)

// React to a text-size change without overriding the deprecated traitCollectionDidChange
registerForTraitChanges([UITraitPreferredContentSizeCategory.self]) { (self: Self, _) in
  let isHuge = self.traitCollection.preferredContentSizeCategory.isAccessibilityCategory
  self.stack.axis = isHuge ? .vertical : .horizontal
}

let row = UIStackView(arrangedSubviews: [icon, title, chevron])
row.axis = .horizontal
row.spacing = 8

// WRONG: every arranged view ends up the same width, and the icon is stretched
// to the row's height because .fill alignment resizes across the axis too.
row.distribution = .fillEqually
row.alignment = .fill

// RIGHT: let the views keep their natural sizes, and say which one absorbs
// the leftover space by lowering its hugging priority.
row.distribution = .fill
row.alignment = .center
icon.setContentHuggingPriority(.required, for: .horizontal)      // never stretches
chevron.setContentHuggingPriority(.required, for: .horizontal)
title.setContentHuggingPriority(.defaultLow, for: .horizontal)   // this one absorbs the slack
title.setContentCompressionResistancePriority(.defaultLow, for: .horizontal) // and truncates first

// The icon needs a size of its own once alignment stops stretching it
NSLayoutConstraint.activate([
  icon.widthAnchor.constraint(equalToConstant: 24),
  icon.heightAnchor.constraint(equalTo: icon.widthAnchor),
])

// One gap that differs from the rest — no spacer view required
row.setCustomSpacing(16, after: title)

// A stack of buttons that really should match: this is the case .fillEqually is for
