actions.spacing = 12

// WRONG: the anchors are activated while badge is still floating with no superview
let badge = UIView()
NSLayoutConstraint.activate([
  badge.topAnchor.constraint(equalTo: card.topAnchor),      // crash: no common ancestor
  badge.trailingAnchor.constraint(equalTo: card.trailingAnchor),
])
card.addSubview(badge)

// RIGHT: hierarchy first, then activation. Activation is what needs the ancestor.
card.addSubview(badge)
badge.translatesAutoresizingMaskIntoConstraints = false
NSLayoutConstraint.activate([
  badge.topAnchor.constraint(equalTo: card.topAnchor, constant: 8),
  badge.trailingAnchor.constraint(equalTo: card.trailingAnchor, constant: -8),
])

// In a cell, constrain to contentView. The cell is an ancestor too, so this
// mistake never crashes — it just lays out against the wrong box.
final class BadgeCell: UITableViewCell {
  private func install() {
    contentView.addSubview(badge)
    badge.leadingAnchor.constraint(equalTo: contentView.layoutMarginsGuide.leadingAnchor).isActive = true
  }
}

// removeFromSuperview() uninstalls every constraint that mentions the view,
// so a stored array has to be reactivated after the view goes back in.
private var badgeConstraints: [NSLayoutConstraint] = []

func setBadgeVisible(_ visible: Bool) {
  guard visible else { badge.removeFromSuperview(); return }
  card.addSubview(badge)
  NSLayoutConstraint.activate(badgeConstraints)   // they were dropped on removal
}

final class BadgeView: UIView {
  private let inset = UIEdgeInsets(top: 4, left: 8, bottom: 4, right: 8)

  var count: Int = 0 {
    didSet {
      guard count != oldValue else { return }
      setNeedsDisplay()                // repaints the same rectangle...
      invalidateIntrinsicContentSize() // ...and this is what re-measures it
    }
  }

  // The whole view, padding included — not just the text
  override var intrinsicContentSize: CGSize {
    let text = "\(count)" as NSString
    let size = text.size(withAttributes: [.font: UIFont.preferredFont(forTextStyle: .caption1)])
    return CGSize(width: ceil(size.width) + inset.left + inset.right,
                  height: ceil(size.height) + inset.top + inset.bottom)
  }
}

// A divider has a natural height but no natural width
final class Divider: UIView {
  override var intrinsicContentSize: CGSize {
    CGSize(width: UIView.noIntrinsicMetric, height: 1 / (window?.screen.scale ?? 2))
  }
}

// sizeThatFits is the manual-layout path: sizeToFit() calls it, Auto Layout does not.
// Implementing only this gives a view that works in a frame-based parent and
// collapses to zero inside constraints.
override func sizeThatFits(_ size: CGSize) -> CGSize { intrinsicContentSize }

func sizeTableHeader() {
  guard let header = tableView.tableHeaderView else { return }

  // Width first: a multi-line label measured at zero width reports one line
  header.frame.size.width = tableView.bounds.width
  header.setNeedsLayout()
  header.layoutIfNeeded()

  let target = CGSize(width: tableView.bounds.width, height: 0)
  let size = header.systemLayoutSizeFitting(
    target,
    withHorizontalFittingPriority: .required,      // this width, exactly
    verticalFittingPriority: .fittingSizeLevel)    // whatever height it needs

  // The comparison is not an optimisation: reassigning unconditionally from a
  // layout callback re-triggers layout forever.
  guard abs(header.frame.height - size.height) > 0.5 else { return }
  header.frame.size.height = size.height
  tableView.tableHeaderView = header               // the table reads the height here
}

override func viewDidLayoutSubviews() {
  super.viewDidLayoutSubviews()
  sizeTableHeader()
}

