// iOS 15+: one constraint, animated in step with the keyboard
composer.translatesAutoresizingMaskIntoConstraints = false
NSLayoutConstraint.activate([
  composer.bottomAnchor.constraint(equalTo: view.keyboardLayoutGuide.topAnchor, constant: -8),
  composer.leadingAnchor.constraint(equalTo: view.leadingAnchor),
  composer.trailingAnchor.constraint(equalTo: view.trailingAnchor),
  // the guide moves the composer; the scroll view above it needs its own bottom
  scrollView.bottomAnchor.constraint(equalTo: composer.topAnchor),
])

view.keyboardLayoutGuide.followsUndockedKeyboard = true   // default is false
view.keyboardLayoutGuide.keyboardDismissPadding = 44
view.keyboardLayoutGuide.usesBottomSafeArea = false       // iOS 17: sit on the very bottom edge

// A different constraint set while the keyboard is undocked
view.keyboardLayoutGuide.setConstraints(
  [composer.bottomAnchor.constraint(equalTo: view.safeAreaLayoutGuide.bottomAnchor, constant: -8)],
  activeWhenAwayFrom: .top)

// The legacy path, done correctly: the notification frame is in SCREEN coordinates
@objc func keyboardWillChangeFrame(_ note: Notification) {
  guard let end = note.userInfo?[UIResponder.keyboardFrameEndUserInfoKey] as? CGRect,
        let window = view.window else { return }
  let inView = view.convert(window.convert(end, from: nil), from: window)
  let overlap = max(0, view.bounds.maxY - inView.minY)   // NOT bounds.height - end.height
  bottomConstraint.constant = -overlap
  view.layoutIfNeeded()
}

// WRONG: the constant is recomputed from the frame this pass produced,
// which dirties the layout and schedules the next pass. Forever.
override func layoutSubviews() {
  super.layoutSubviews()
  insetConstraint.constant = bounds.width * 0.1
  layoutIfNeeded()                       // and this makes it recurse immediately
}

// RIGHT: a guard makes it converge — the second pass finds nothing to change
override func layoutSubviews() {
  super.layoutSubviews()
  let wanted = bounds.width * 0.1
  if abs(insetConstraint.constant - wanted) > 0.5 {
    insetConstraint.constant = wanted    // no layoutIfNeeded; the pass continues on its own
  }
  gradient.frame = bounds                // safe: touches no constraint
  mask?.frame = bounds
}

// BETTER: drive the constraint from data, not from the geometry it produces
func apply(_ style: CardStyle) {
  insetConstraint.constant = style.inset
  setNeedsLayout()
}

// Diagnose it: Edit Scheme -> Run -> Arguments Passed On Launch
//   -UIViewLayoutFeedbackLoopDebuggingThreshold 100
// UIKit throws with a diagnostic once one view lays out 100 times in a pass.

