// RIGHT: the trait describes the space this view actually got
private func applyLayout() {
  let regular = traitCollection.horizontalSizeClass == .regular
  columns.axis = regular ? .horizontal : .vertical
  sidebarWidth.isActive = regular
}

override func viewDidLoad() {
  super.viewDidLoad()
  applyLayout()
  // iOS 17: one closure per trait, instead of the deprecated traitCollectionDidChange
  registerForTraitChanges([UITraitHorizontalSizeClass.self]) { (self: Self, _) in
    self.applyLayout()
  }
}

// Rotation: animate alongside it, don't snap at the end
override func viewWillTransition(to size: CGSize,
                                 with coordinator: UIViewControllerTransitionCoordinator) {
  super.viewWillTransition(to: size, with: coordinator)
  coordinator.animate { _ in self.header.axis = size.width > size.height ? .horizontal : .vertical }
}

